INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia oncológica de pescoço apresenta, no 3º DPO, incapacidade de realizar o levantamento de ombro (shrug) e dificuldade em abduzir o braço acima de 90 graus. Qual o nervo provavelmente lesionado no esvaziamento cervical?", "options": {"a": "Nervo Vago.", "b": "Nervo Acessório (XI par craniano).", "c": "Nervo Glossofaríngeo.", "d": "Nervo Hipoglosso.", "e": "Nervo Frênico."}, "answer": "b", "rationale": "O nervo acessório inerva os músculos esternocleidomastoideo e trapézio. Sua lesão causa queda do ombro e incapacidade de elevação escapular.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Lesão clássica em esvaziamentos cervicais radicais.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Nervo Acessório", "Complicações"]}', 281, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma tireoidectomia, ao pedir para o paciente colocar a língua para fora, observa-se desvio para o lado direito. Qual o nervo lesionado?", "options": {"a": "Nervo Hipoglosso (XII) direito.", "b": "Nervo Hipoglosso (XII) esquerdo.", "c": "Nervo Laríngeo superior.", "d": "Nervo Trigêmeo.", "e": "Nervo Facial."}, "answer": "a", "rationale": "O nervo hipoglosso inerva a musculatura da língua. Na lesão unilateral, a língua desvia para o mesmo lado da lesão (ipsilateral) por ação do músculo genioglosso contralateral.", "option_rationales": {"a": "Correta. Desvio para o lado lesionado.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Hipoglosso", "Nervos"]}', 282, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''mediastinite aguda'' após uma esternotomia para cirurgia cardíaca, manifestando-se por dor retroesternal, febre e instabilidade do próprio esterno, é:", "options": {"a": "Contaminação da ferida operatoria por estafilococos da pele ou deiscência profunda.", "b": "Inalação de pó doméstico.", "c": "Derrame pleural isolado.", "d": "Auscência de drenos.", "e": "Excesso de repouso."}, "answer": "a", "rationale": "A mediastinite é uma complicação grave (mortalidade de 10-40%) que exige desbridamento cirúrgico e antibioticoterapia prolongada.", "option_rationales": {"a": "Correta. Etiologia infecciosa profunda.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Mediastinite", "Esternotomia"]}', 283, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente diabético tipo 2 em uso de Empagliflozina (inibidor de SGLT2) é submetido a cirurgia ortopédica. Ele desenvolve mal-estar, dor abdominal e acidose metabólica com gap aniônico elevado. A glicemia capilar é de 140 mg/dL. Qual o diagnóstico provável?", "options": {"a": "Cetoacidose Diabética Euglicêmica.", "b": "Estado Hiperosmolar.", "c": "Hipoglicemia grave.", "d": "Choque Séptico por pneumonia.", "e": "Lactacidose por estresse."}, "answer": "a", "rationale": "Os inibidores de SGLT2 podem causar CAD sem hiperglicemia marcante (euglicêmica) no período perioperatório, o que pode atrasar o diagnóstico se o médico focar apenas no valor da glicemia.", "option_rationales": {"a": "Correta. Complicação metabólica específica de classe medicamentosa.", "b": "Incorreta. Exige glicemia muito alta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Endocrinologia", "Pós-operatório", "DKA", "SGLT2"]}', 284, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Síndrome de Realimentação'' (Refeeding Syndrome) em pacientes desnutridos que voltam a receber calorias rapidamente no pós-operatório caracteriza-se laboratorialmente por:", "options": {"a": "Hipercalemia e Hiperfosfatemia.", "b": "Hipofosfatemia exagerada, hipocalemia e hipomagnesemia.", "c": "Aumento do sódio apenas.", "d": "Queda da creatinina.", "e": "Aumento da glicemia isolado."}, "answer": "b", "rationale": "O aporte de glicose estimula a insulina, que leva o fósforo (já estocado em níveis baixos) para dentro das células, causando uma queda drástica no sangue que impede a produção de ATP e causa falência muscular/respiratória.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Distúrbios eletrolíticos clássicos da realimentação.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Nutrição", "Pós-operatório", "Refeeding", "Fósforo"]}', 285, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de aorta toracoabdominal, o paciente acorda com paraplegia e perda da sensibilidade dolorosa e térmica abaixo do nível da lesão, mas preservando a sensibilidade vibratória e propriocepção. Qual a síndrome medular instalada?", "options": {"a": "Síndrome de Brown-Séquard.", "b": "Síndrome da Artéria Espinal Anterior.", "c": "Síndrome do Cone Medular.", "d": "Síndrome de Cauda Equina.", "e": "Transecção medular completa."}, "answer": "b", "rationale": "A isquemia medular é um risco severo na cirurgia aórtica. A artéria de Adamkiewicz supre os 2/3 anteriores da medula, poupando os cordões posteriores (vibração/propriocepção).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Isquemia medular específica por clampeamento aórtico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cirurgia Vascular", "Pós-operatório", "Aorta", "Paraplegia"]}', 286, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal medida preventiva para reduzir o risco de paraplegia em cirurgias complexas de aorta torácica aberta ou endovascular?", "options": {"a": "Hipertensão induzida peroperatoria.", "b": "Drenagem do Líquido Cefalorraquidiano (LCR) por cateter lombar para reduzir a pressão intracanal e melhorar a pressão de perfusão medular.", "c": "Resfriamento das pernas apenas.", "d": "Uso de doses altas de aspirina.", "e": "Repouso absoluto por 30 dias."}, "answer": "b", "rationale": "Ao reduzir a pressão do líquor, aumenta-se o gradiente entre a artéria e o canal espinal, favorecendo a perfusão da medula isquêmica.", "option_rationales": {"a": "Incorreta. Hipertensão controlada pode ajudar mas a drenagem é a medida pilar.", "b": "Correta. Técnica padrão de proteção medular.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Vascular", "Pós-operatório", "Medula", "Drenagem LCR"]}', 287, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal desenvolve quadro de soluços persistentes e intratáveis no pós-operatório. Isso pode ser um sinal de irritação de qual nervo?", "options": {"a": "Nervo Vago.", "b": "Nervo Frênico.", "c": "Nervo Radial.", "d": "Nervo Hipoglosso.", "e": "Nervo Obturador."}, "answer": "b", "rationale": "O nervo frênico inerva o diafragma. Estímulos irritativos (como coleções subfrênicas, distensão gástrica ou compressão) podem causar contrações reflexas rítmicas (soluços).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Nervo responsável pelo mecanismo do soluço.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Frênico", "Soluço"]}', 288, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''enfisema subcutâneo'' (presença de ar sob a pele, com crepitação à palpação) no pescoço e tórax superior após uma traqueostomia eletiva sugere:", "options": {"a": "Cicatriz excessiva.", "b": "Vazamento de ar ao redor da cânula para os tecidos moles, podendo indicar posicionamento incorreto ou sutura de pele muito apertada impedindo a saída do ar residual.", "c": "Infecção por fungos.", "d": "Auscência de pulmão.", "e": "Flebite jugular."}, "answer": "b", "rationale": "O ar escapa da traqueia para os tecidos fasciais do pescoço. Pode evoluir para pneumomediastino ou pneumotórax se não for monitorado.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação técnica imediata da traqueostomia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Traqueostomia", "Enfisema"]}', 289, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "O ''Escore de Aldrete'' é utilizado na sala de recuperação pós-anestésica (SRPA) para avaliar qual critério fundamental?", "options": {"a": "Nível de dor do paciente.", "b": "Condições de alta segura para a enfermaria (baseado em consciência, respiração, circulação, saturação e atividade motora).", "c": "Risco de infecção urinária.", "d": "Necessidade de nova cirurgia.", "e": "Quantidade de sangue perdido na cirurgia."}, "answer": "b", "rationale": "É uma escala de 0 a 10 que sistematiza a prontidão do paciente para deixar a monitorização intensiva da SRPA.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Escala de avaliação de recuperação anestésica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Aldrete", "Alta SRPA"]}', 290, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a laminectomia lombar apresenta no 2º DPO dor severa em região sacra, retenção urinária súbita e perda de sensibilidade em ''sela'' (perineo e região perianal). Qual a complicação neurológica de emergência?", "options": {"a": "AVC cerebral.", "b": "Síndrome da Cauda Equina (geralmente por hematoma extradural compressivo).", "c": "Hérnia de hiato súbita.", "d": "Crise de ansiedade.", "e": "Fraqueza por jejum."}, "answer": "b", "rationale": "O hematoma no local da cirurgia de coluna pode comprimir as raízes nervosas terminais (cauda equina), exigindo descompressão cirúrgica imediata para evitar sequelas permanentes de esfíncter.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Emergência neurocirúrgica pós-operatória.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Neurocirurgia", "Pós-operatório", "Cauda Equina", "Emergência"]}', 291, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação do uso do ''dreno de sucção'' (como o dreno de Portovac ou Jackson-Pratt) quando colocado muito próximo a uma anastomose intestinal?", "options": {"a": "Aumento da motilidade intestinal.", "b": "Erosão da anastomose por sucção mecânica e pressão negativa constante, podendo favorecer a ocorrência de fístula.", "c": "Infecção por vírus.", "d": "Paralisia das pernas.", "e": "Cura mais rápida."}, "answer": "b", "rationale": "O dreno não deve tocar a sutura; a pressão negativa pode ''sugar'' o tecido da anastomose, comprometendo a vascularização e integridade.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Risco técnico do posicionamento de drenos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Drenos", "Fístula"]}', 292, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de ressecção de tumor em parótida profunda, o paciente apresenta ptose palpebral, miose e enoftalmia (tríade de Horner) no lado operado. Qual cadeia nervosa foi acometida?", "options": {"a": "Cadeia Simpática Cervical.", "b": "Nervo Facial.", "c": "Nervo Hipoglosso.", "d": "Nervo Glossofaríngeo.", "e": "Plexo Braquial."}, "answer": "a", "rationale": "A Síndrome de Horner é causada pela disrupção da inervação simpática para o olho e face, que passa pelo pescoço próxima à bainha carotídea.", "option_rationales": {"a": "Correta. Origem anatômica da síndrome de Horner.", "b": "Incorreta. Causaria paralisia facial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Horner", "Simpático"]}', 293, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a laparotomia de urgência por úlcera perfurada apresenta, no 5º DPO, dor abdominal difusa e o cirurgião nota saída imediata de bile e fezes pelo dreno abdominal. Qual o diagnóstico e conduta?", "options": {"a": "Evolução normal; manter observação.", "b": "Fístula enterobiliar ou deiscência de anastomose; geralmente exige reoperação para controle do foco infeccioso.", "c": "Apenas trocar o dreno por um maior.", "d": "Uso de apenas pomada local.", "e": "Iniciar dieta sólida abundante."}, "answer": "b", "rationale": "A saída de conteúdo entérico pelo dreno é diagnóstico de deiscência de sutura ou perfuração inadvertida. O tratamento inicial foca na estabilização e muitas vezes re-intervenção.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico de deiscência total.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Pioraria a contaminação."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula", "Manejo"]}', 294, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Fecaloma'' no pós-operatório (especialmente em idosos e ortopédicos) deve-se principalmente a:", "options": {"a": "Excesso de fibras na dieta.", "b": "Combinação de imobilidade, uso de opioides e desidratação, levando a desidratação e impacto de fezes no reto.", "c": "Infecção por vírus do reto.", "d": "Auscência de vesícula biliar.", "e": "Ingestão exagerada de líquidos."}, "answer": "b", "rationale": "Os opioides reduzem drasticamente a motilidade colônica. Se o paciente não deambular e não for hidratado, as fezes endurecem e formam uma massa obstrutiva.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fatores de risco cirúrgicos para constipação severa.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fecaloma", "Opioides"]}', 295, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente no pós-operatório de cirurgia cardíaca apresenta no 10º dia febre, derrame pleural, atrito pericárdico e aumento de marcadores inflamatórios. Qual a síndrome imunomediada tardia suspeita?", "options": {"a": "Sindrome de Mendelson.", "b": "Sindrome de Dressler (Pericardite pós-pericardiotomia).", "c": "Sindrome de Ogilvie.", "d": "Sindrome de Zollinger-Ellison.", "e": "Sindrome de Horner."}, "answer": "b", "rationale": "A síndrome de Dressler é uma reação autoimune contra o pericárdio após abertura ou trauma cardíaco, tratada geralmente com AINEs e colchicina.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação inflamatória tardia pós-cardíaca.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Cardíaca", "Pós-operatório", "Dressler", "Pericardite"]}', 296, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação do uso prolongado de cateteres venosos centrais localizados em veia subclávia, no que diz respeito ao controle radiológico de longo prazo?", "options": {"a": "Dureza da pele.", "b": "Estenose de veia subclávia, que pode dificultar futuros acessos ou causar edema crônico do membro superior.", "c": "Perda de pelos no peito.", "d": "Alergia ao silicone do dreno.", "e": "Melhora da função renal."}, "answer": "b", "rationale": "O trauma mecânico repetido e a resposta inflamatória ao cateter geram fibrose e estenose venosa tardia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação vascular crônica de acessos centrais.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "Acesso Central", "Estenose"]}', 297, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma lobectomia pulmonar, observa-se escape aéreo persistente pelo dreno de tórax (borbulhamento constante no frasco) por mais de 5 a 7 dias. Esta condição é denominada:", "options": {"a": "Pneumonia aguda.", "b": "Fístula Alveolopleural persistente ou escape aéreo prolongado.", "c": "Edema pulmonar unilateral.", "d": "Hemorragia pulmonar.", "e": "Cura retardada."}, "answer": "b", "rationale": "É uma falha no fechamento do parênquima pulmonar operado ou insuficiência da sutura brônquica.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Definição de complicação pós-ressecção pulmonar.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Torácica", "Pós-operatório", "Escape Aéreo", "Fístula"]}', 298, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''hipocalemia'' no pós-operatório de cirurgias gastrointestinais extensas, excluindo o uso de diuréticos, é:", "options": {"a": "Perda de secreções gastrointestinais (vômitos ou drenagem gástrica) associada à alcalose e troca renal de hidrogênio por potássio.", "b": "Reposição excessiva de sódio.", "c": "Falta de exercícios físicos.", "d": "Consumo de banana reduzido.", "e": "Anestesia local."}, "answer": "a", "rationale": "Perdas por SNG ou vômitos são ricas em potássio e cloro, gerando um ciclo metabólico que espolia potássio pelo rim.", "option_rationales": {"a": "Correta. Mecanismo metabólico clássico.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Clínica Médica", "Pós-operatório", "Hipocalemia", "Eletrólitos"]}', 299, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia no 12 de outubro apresenta dreno de tórax oscilando mas sem drenagem há 24h. O Raio-x mostra pulmão totalmente expandido. Qual a conduta?", "options": {"a": "Trocar o dreno.", "b": "Retirar o dreno com segurança (fase de desmame finalizada).", "c": "Aumentar a pressão de sucção.", "d": "Manter o dreno por mais 30 dias.", "e": "Pedir tomografia urgente."}, "answer": "b", "rationale": "A ausência de débito e a expansão pulmonar confirmada radiologicamente indicam que o dreno já cumpriu sua função.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Manejo de retirada de dreno de tórax.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Torácica", "Pós-operatório", "Dreno de Tórax", "Retirada"]}', 300, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal complicação do ''uso inadvertido de fármacos vasopressores'' (como noradrenalina) em altas doses para compensar uma hipovolemia não corrigida é:", "options": {"a": "Melhora da função renal.", "b": "Isquemia de extremidades (pontas de dedos e pés) e isquemia mesentérica por vasoconstrição periférica excessiva.", "c": "Aumento do apetite.", "d": "Sonolência intensa.", "e": "Drenagem biliar."}, "answer": "b", "rationale": "As drogas vasoativas agem contra uma falta de volume; se não houver sangue/líquido, elas apenas ''fecham'' os vasos para órgãos vitais, sacrificando a periferia e o intestino.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Risco de uso crônico de aminas em doses altas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Terapia Intensiva", "Pós-operatório", "Vasopressores", "Isquemia"]}', 301, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de grande porte, observa-se que o paciente apresenta oligúria (débito < 0,5 ml/kg/h). Sabendo que o paciente não urinou e após realizar uma manobra de passar sonda urinária houve saída de 1000 ml de urina imediata. Qual a etiologia da IRA?", "options": {"a": "Pré-renal.", "b": "Pós-renal (obstrutiva) por retenção urinária aguda ou cateterismo falho.", "c": "Renal (NTA).", "d": "Transfusão errada.", "e": "Flebite gástrica."}, "answer": "b", "rationale": "Se a urina sai em grande quantidade após a sondagem, o problema estava na saída (bexiga), configurando uma causa pós-renal.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Diagnóstico de retenção urinária.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Urologia", "Pós-operatório", "IRA", "Retenção"]}', 302, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma herniorrafia inguinal, observa-se que o testículo ipsilateral à cirurgia está inchado, doloroso e com tonalidade escura 24 horas após o procedimento. Qual a complicação vascular provável?", "options": {"a": "Epididimite aguda.", "b": "Trombose do plexo pampiniforme ou lesão iatrogênica da artéria testicular durante a manipulação do cordão espermático (Infarto Testicular).", "c": "Infecção por vírus do herpes.", "d": "Hernia recidivada imediata.", "e": "Hérnia de hiato."}, "answer": "b", "rationale": "A manipulação agressiva do cordão espermático pode comprometer o suprimento ou a drenagem venosa do testículo, levando ao infarto isquêmico.", "option_rationales": {"a": "Incorreta. Epididimite seria inflamatória e tardia.", "b": "Correta. Complicação vascular específica da cirurgia inguinal.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Herniorrafia", "Testículo"]}', 303, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Íleo Biliar'' (obstrução mecânica por cálculo biliar que migrou) ocorre após qual evento fístular?”, "options": {"a": "Fístula na uretra.", "b": "Fístula Colecisto-duodenal (comunica a vesícula diretamente com o duodeno).", "c": "Fístula anal.", "d": "Fístula esofágica.", "e": "Fístula biliar externa pela pele."}, "answer": "b", "rationale": "A inflamação crônica biliar erode a parede da vesícula e do duodeno, permitindo que um cálculo grande passe para o intestino e impacte na válvula ileocecal.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Mecanismo fístular bilioentérico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Íleo Biliar", "Fístula"]}', 304, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente que desenvolve ''seroma'' no pós-operatório (coleção de líquido citrino estéril sob a ferida) deve ser manejado prioritariamente com:", "options": {"a": "Abertura completa da ferida e antibióticos fortes.", "b": "Aspiração com agulha e técnica estéril se houver tensão ou dor; compressão local externa para ocluir o espaço morto.", "c": "Tratamento apenas com pomadas cicatrizantes.", "d": "Não fazer nada nunca.", "e": "Reoperar para fechar o dreno."}, "answer": "b", "rationale": "O seroma é um acúmulo de líquido linfático e inflamatório num espaço morto. A aspiração resolve a tensão e a compressão evita que o líquido se forme novamente.", "option_rationales": {"a": "Incorreta. Seroma não é pus (infecção).", "b": "Correta. Conduta padrão para seroma sintomático.", "c": "Incorreta.", "d": "Incorreta. Grandes seromas podem infectar secundariamente se abandonados.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Seroma", "Manejo"]}', 305, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual complicação de cicatrização se caracteriza pela abertura parcial apenas da pele e do subcutâneo, mantendo a fáscia aponeurótica íntegra?", "options": {"a": "Evisceração.", "b": "Deiscência superficial de sutura.", "c": "Eventração crônica.", "d": "Hérnia incisional tardia.", "e": "Fístula estercoral."}, "answer": "b", "rationale": "Diferente da deiscência total (aponeurótica), na superficial o conteúdo abdominal permanece protegido pela parede muscular íntegra.", "option_rationales": {"a": "Incorreta. Evisceração é a deiscência total.", "b": "Correta. Definição de complicação limitada ao plano superficial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Terminologia"]}', 306, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma neurocirurgia, observa-se que o paciente apresenta polidipsia (sede excessiva) e poliúria com urina muito diluída. Ao dosar o sódio está em 156. Qual o tratamento farmacológico de escolha para este Diabetes Insipidus Central?", "options": {"a": "Insulina rápida.", "b": "Desmopressina (DDAVP) - análogo sintético do ADH.", "c": "Furosemida.", "d": "Glicose 50% isolada.", "e": "Dipirona."}, "answer": "b", "rationale": "O DDAVP repõe a função do ADH ausente, reduzindo a diurese e normalizando o sódio.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Tratamento específico do DI central.", "c": "Incorreta. Pioraria a desidratação livre.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Neurocirurgia", "Pós-operatório", "DI", "DDAVP"]}', 307, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''embolia venosa gordurosa'' em pacientes ortopédicos?", "options": {"a": "Fratura por estresse do pé.", "b": "Fraturas de grandes ossos longos (como Fêmur) ou cirurgias de artroplastia que manipulam o canal medular rico em gordura.", "c": "Corte na pele externo apenas.", "d": "Alergia ao ferro da maca.", "e": "Uso de gel na pele."}, "answer": "b", "rationale": "A gordura da medula óssea cai na circulação venosa durante o trauma ou o preparo cirúrgico do osso.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Fisiopatologia clássica da embolia gordurosa.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Ortopedia", "Pós-operatório", "Embolia Gordurosa", "Etiologia"]}', 308, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente no 5º DPO de uma cirurgia de grande porte queixa-se de uma mancha preta em sua calça na região das costas. Ao examiná-lo, o cirurgião nota uma ferida necrozada de 10 cm na região sacra por decúbito. O que ocorreu?", "options": {"a": "Infeccção por fungos da cama.", "b": "Escara de decúbito (Lesão por Pressão) por falta de mudança de decúbito sistemática.", "c": "Câncer de pele súbito.", "d": "Hemangioma reacional.", "e": "Alergia ao iodo."}, "answer": "b", "rationale": "A pressão mantida sobre o tecido reduz a perfusão capilar, levando a isquemia e necrose de pele e tecidos profundos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação de permanência prolongada no leito.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Enfermagem", "Pós-operatório", "Escara", "Pressão"]}', 309, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia vascular com uso de cateter de embolectomia (Fogarty), observa-se que o paciente apresenta no 2º DPO urina cor de ''coca-cola'' e dor muscular severa no membro operado. A CPK é de 45.000 U/L. Qual a complicação sistêmica mais temida que pode levá-lo ao óbito rápido?”, "options": {"a": "Cegueira súbita.", "b": "Insuficiência Renal Aguda por mioglobinúria (necrose tubular por deposição de mioglobina).", "c": "Hepatite medicamentosa.", "d": "Pneumoperitônio.", "e": "Artrite reumatoide."}, "answer": "b", "rationale": "A rabdomiólise libera mioglobina que é nefrotóxica. A prevenção envolve hidratação vigorosa e, às vezes, alcalinização urinária.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação renal grave da rabdomiólise.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Vascular", "Pós-operatório", "Rabdomiólise", "IRA"]}', 310, 'draft')
